function csv(s){let [h,...ls]=s.trim().split(/\r?\n/),ks=h.split(',');return ls.filter(x=>x.split(',')[0]).map(l=>{let v=l.split(','),o={};ks.forEach((k,i)=>o[k]=i?+v[i]:v[i]);return o})}
function norm(k,log=false){let a=data.map(r=>log?Math.log1p(r[k]):r[k]),lo=Math.min(...a),hi=Math.max(...a);return r=>((log?Math.log1p(r[k]):r[k])-lo)/(hi-lo)}
function enrich(){data.forEach(r=>{r.name=N[r.Concelho];r.internet=r.UI/r.Pt*100;r.mobile=r.UM/r.Pt*100;r.gap=Math.max(0,r.Pt-r.UI);r.unemployment=r.Des/(r.Emp+r.Des)*100;r.school=r.AFRE/(r.AFRE+r.ANFRE)*100;r.conversion=Math.max(0,(r.UM-r.UI)/r.Pt*100);r.edu=(r.ANFRE/(r.AFRE+r.ANFRE)*100+r['PAE(14-20)']+r['PAE(6-16)'])/3});let ns={market:norm('Pt',1),gap:norm('gap',1),density:norm('DEN_POP',1),employment:norm('Emp',1),conversion:norm('conversion'),education:norm('edu')};data.forEach(r=>{r.c={};Object.keys(ns).forEach(k=>r.c[k]=ns[k](r))});scores()}
function scores(){data.forEach(r=>r.score=Math.round(Object.keys(w).reduce((s,k)=>s+r.c[k]*w[k],0)))}
function strategy(r){return r.Pt>30000&&r.DEN_POP>150?t('scaleStrategy'):r.conversion>8?t('conversionStrategy'):r.internet<50?t('reachStrategy'):t('selectiveStrategy')}
function opts(id,a){let e=document.getElementById(id),v=e.value;e.innerHTML=a.map(x=>`<option value="${x[0]}">${t(x[1])}</option>`).join('');if(a.some(x=>x[0]===v))e.value=v}
function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));document.querySelectorAll('[data-lang]').forEach(e=>e.classList.toggle('active',e.dataset.lang===lang));document.getElementById('search').placeholder=t('searchPlaceholder');opts('metricSelect',[['score','metricScore'],['internet','metricInternet'],['gap','metricGap']]);opts('sortMetric',[['score','metricScore'],['population','metricPopulation'],['internet','metricInternet'],['gap','metricGap'],['density','metricDensity']]);opts('investmentType',[['infrastructure','infra'],['service','service'],['product','product'],['inclusion','inclusion']]);opts('priorityPreset',[['balanced','balanced'],['scale','scale'],['gap','gapPriority'],['density','densityPriority'],['impact','impact']]);document.getElementById('decisionHeadline').textContent=t('decision');render()}
function kpis(){let total=k=>data.reduce((s,r)=>s+r[k],0),p=total('Pt'),u=total('UI');document.getElementById('kpis').innerHTML=[[t('population'),fmt(p),t('datasetTotal')],[t('internetUsers'),fmt(u),t('recordedUsers')],[t('internetPen'),pct(u/p*100),t('ofPopulation')],[t('potentialUsers'),fmt(p-u),t('people')]].map(x=>`<article class="kpi"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></article>`).join('')}
function chart(){let m=document.getElementById('metricSelect').value,k=m==='score'?'score':m==='internet'?'internet':'gap',a=[...data].sort((x,y)=>y[k]-x[k]).slice(0,7),mx=a[0][k];document.getElementById('barChart').innerHTML=a.map(r=>`<div class="bar-item"><span class="bar-value">${k==='internet'?pct(r[k]):fmt(r[k])}</span><div class="bar" style="height:${Math.max(6,r[k]/mx*205)}px"></div><span class="bar-label">${r.name}</span></div>`).join('')}
function insights(){let a=[...data].sort((x,y)=>y.score-x.score)[0],b=[...data].sort((x,y)=>y.gap-x.gap)[0],c=[...data].sort((x,y)=>y.conversion-x.conversion)[0],d=[...data].sort((x,y)=>y.DEN_POP-x.DEN_POP)[0],xs=lang==='pt'?[`${a.name} alcança o maior índice composto (${a.score}/100).`,`${b.name} concentra ${fmt(b.gap)} potenciais novos utilizadores.`,`${c.name} tem a maior diferença móvel–internet (${pct(c.conversion)}).`,`${d.name} apresenta a maior densidade (${fmt(d.DEN_POP,1)} hab./km²).`]:[`${a.name} has the highest composite score (${a.score}/100).`,`${b.name} has ${fmt(b.gap)} potential new users.`,`${c.name} has the widest mobile–internet gap (${pct(c.conversion)}).`,`${d.name} has the highest density (${fmt(d.DEN_POP,1)} people/km²).`];document.getElementById('insights').innerHTML=xs.map(x=>`<li><span>${x}</span></li>`).join('')}
function islands(){let mx=Math.max(...data.map(r=>r.Pt));document.getElementById('islandMatrix').innerHTML=Object.entries(IS).map(([i,cs])=>`<section class="island-group"><h3>${i}</h3><div class="island-dots">${cs.map(c=>{let r=data.find(x=>x.Concelho===c),z=30+Math.sqrt(r.Pt/mx)*32;return `<button class="muni-dot" data-profile="${c}" style="width:${z}px;height:${z}px;background:hsl(${175-r.score*.65} 58% 38%)" title="${r.name} · ${r.score}/100">${c}</button>`}).join('')}</div></section>`).join('')}
function ranking(){let q=document.getElementById('search').value.toLowerCase(),k={score:'score',population:'Pt',internet:'internet',gap:'gap',density:'DEN_POP'}[sort],a=[...data].filter(r=>(r.name+r.Concelho).toLowerCase().includes(q)).sort((x,y)=>y[k]-x[k]);document.getElementById('rankHead').innerHTML=`<tr><th>#</th><th>${t('municipality')}</th><th>${t('score')}</th><th>${t('population')}</th><th>${t('internetPen')}</th><th>${t('mobilePen')}</th><th>${t('density')}</th><th>${t('potentialUsers')}</th><th>${t('strategy')}</th><th>${t('profile')}</th></tr>`;document.getElementById('rankBody').innerHTML=a.length?a.map((r,i)=>`<tr><td>${i+1}</td><td><b>${r.name}</b><br><small>${r.Concelho}</small></td><td><span class="score-pill">${r.score}</span></td><td>${fmt(r.Pt)}</td><td>${pct(r.internet)}</td><td>${pct(r.mobile)}</td><td>${fmt(r.DEN_POP,1)}</td><td>${fmt(r.gap)}</td><td class="strategy">${strategy(r)}</td><td><button class="profile-link" data-profile="${r.Concelho}">${t('viewProfile')}</button></td></tr>`).join(''):`<tr><td colspan="10" class="empty">${t('noResults')}</td></tr>`}
function compare(){let old=[...document.querySelectorAll('.compare-select')].map(x=>x.value),ds=old.length?old:['PR','SV','SC'];document.getElementById('compareSelectors').innerHTML=ds.map((v,i)=>`<label><span>${t('choice')} ${i+1}</span><select class="compare-select">${data.map(r=>`<option value="${r.Concelho}" ${r.Concelho===v?'selected':''}>${r.name}</option>`).join('')}</select></label>`).join('');compareResults()}
function compareResults(){let rs=[...document.querySelectorAll('.compare-select')].map(x=>data.find(r=>r.Concelho===x.value));if(!rs.length)return;let ms=[['score','score',100,0],['population','Pt',Math.max(...rs.map(r=>r.Pt)),0],['internetPen','internet',100,1],['mobilePen','mobile',100,1],['unemployment','unemployment',Math.max(...rs.map(r=>r.unemployment)),1],['schoolParticipation','school',100,1],['density','DEN_POP',Math.max(...rs.map(r=>r.DEN_POP)),0]];document.getElementById('compareResults').innerHTML=`<article class="panel comparison-table"><table><thead><tr><th>${t('indicator')}</th>${rs.map(r=>`<th>${r.name}</th>`).join('')}</tr></thead><tbody>${ms.map(m=>`<tr><td>${t(m[0])}</td>${rs.map(r=>`<td><div class="metric-bar"><span>${m[3]?pct(r[m[1]]):fmt(r[m[1]],m[1]==='DEN_POP'?1:0)}</span><div class="metric-track"><div class="metric-fill" style="width:${Math.min(100,r[m[1]]/m[2]*100)}%"></div></div></div></td>`).join('')}</tr>`).join('')}</tbody></table></article><div class="compare-cards">${rs.map(r=>`<article class="panel compare-card"><p class="eyebrow">${r.Concelho} · ${t('score')} ${r.score}</p><h3>${r.name}</h3><strong>${t('marketStrengths')}</strong><ul><li>${r.score>avg('score')?t('aboveAverage'):strategy(r)}</li><li>${r.Pt>avg('Pt')?t('largeMarket'):t('selectiveStrategy')}</li></ul><strong>${t('riskSignals')}</strong><ul><li>${r.internet<avg('internet')?t('belowInternet'):t('riskText')}</li></ul><button class="profile-link" data-profile="${r.Concelho}">${t('viewProfile')}</button></article>`).join('')}</div>`}
const WL={market:'marketWeight',gap:'gapWeight',density:'densityWeight',employment:'employmentWeight',conversion:'conversionWeight',education:'educationWeight'};
function simulator(){document.getElementById('weightControls').innerHTML=Object.keys(w).map(k=>`<div class="weight-row"><label><span>${t(WL[k])}</span><input class="weight-input" data-weight="${k}" type="range" min="0" max="60" value="${w[k]}"></label><output>${w[k]}%</output></div>`).join('');document.getElementById('weightTotal').textContent='100%';let n=+document.getElementById('topN').value,type=document.getElementById('investmentType').value,a=[...data].sort((x,y)=>y.score-x.score).slice(0,n),action=t({infrastructure:'infraAction',service:'serviceAction',product:'productAction',inclusion:'inclusionAction'}[type]);document.getElementById('topNValue').value=n;document.getElementById('simHeadline').textContent=`${n} ${t('topCandidates')}`;document.getElementById('simResults').innerHTML=a.map((r,i)=>`<article class="panel recommendation-card"><span class="position">${i+1}</span><p class="eyebrow">${r.Concelho}</p><h3>${r.name}</h3><div class="score-line"><div class="score-ring" style="--score:${r.score}"><span>${r.score}</span></div><p>${action}</p></div><strong>${t('evidence')}</strong><div class="evidence"><span>${fmt(r.Pt)} ${t('people')}</span><span>${pct(r.internet)}</span><span>${fmt(r.gap)} ${t('potentialUsers').toLowerCase()}</span></div><p class="risk-note"><strong>${t('risk')}:</strong> ${t('riskText')}</p><button class="profile-link" data-profile="${r.Concelho}">${t('viewProfile')}</button></article>`).join('')}
function methodology(){document.getElementById('formulaCards').innerHTML=Object.keys(w).map(k=>`<div class="formula-card"><strong>${w[k]}% · ${t(WL[k])}</strong><span>${t('normalized')}</span></div>`).join('');let fs=['UI ÷ Pt × 100','UM ÷ Pt × 100','Des ÷ (Emp + Des) × 100','AFRE ÷ (AFRE + ANFRE) × 100','max(0, Pt − UI)','Pt ÷ Alojamento'];document.getElementById('formulaList').innerHTML=fs.map(x=>`<div class="formula-item">${x}</div>`).join('');document.getElementById('dictionaryBody').innerHTML=D.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}
function render(){if(!data.length)return;kpis();chart();insights();islands();ranking();compare();simulator();methodology();document.getElementById('pageTitle').textContent=t({overview:'overviewTitle',ranking:'rankingTitle',compare:'compareTitle',simulator:'simulatorTitle',methodology:'methodologyTitle'}[view])}
function setWeight(k,v){w[k]=v;let d=Object.values(w).reduce((a,b)=>a+b,0)-100,os=Object.keys(w).filter(x=>x!==k).sort((a,b)=>w[b]-w[a]);for(let x of os){if(!d)break;if(d>0){let q=Math.min(d,w[x]);w[x]-=q;d-=q}else{let q=Math.min(-d,60-w[x]);w[x]+=q;d+=q}}scores();render()}
function profile(c){let r=data.find(x=>x.Concelho===c);document.getElementById('profileContent').innerHTML=`<article class="profile"><p class="eyebrow">${r.Concelho}</p><h2>${r.name}</h2><div class="profile-grid">${[[t('score'),r.score+'/100'],[t('population'),fmt(r.Pt)],[t('internetPen'),pct(r.internet)],[t('mobilePen'),pct(r.mobile)],[t('unemployment'),pct(r.unemployment)],[t('density'),fmt(r.DEN_POP,1)]].map(x=>`<div class="profile-metric"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><h3>${t('scoreBreakdown')}</h3><div class="profile-breakdown">${Object.keys(w).map(k=>`<div class="breakdown-row"><span>${t(WL[k])}</span><div class="metric-track"><div class="metric-fill" style="width:${r.c[k]*100}%"></div></div><strong>${Math.round(r.c[k]*w[k])}</strong></div>`).join('')}</div><div class="profile-action"><strong>${t('suggestedAction')}</strong><p>${strategy(r)}</p></div><p>${t('observedRateNote')}</p></article>`;document.getElementById('profileDialog').showModal()}
function show(v){view=v;history.replaceState(null,'','#'+v);document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===v));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v));render();document.querySelector('.sidebar').classList.remove('open');scrollTo(0,0)}
function exportRows(a,name){let h=lang==='pt'?['Município','Código','Índice','População','Internet (%)','Móvel (%)','Potencial']:['Municipality','Code','Score','Population','Internet (%)','Mobile (%)','Potential'],rs=[h,...a.map(r=>[r.name,r.Concelho,r.score,r.Pt,r.internet.toFixed(1),r.mobile.toFixed(1),r.gap])],b=new Blob(['\ufeff'+rs.map(x=>x.join(',')).join('\n')]),u=URL.createObjectURL(b),el=document.createElement('a');el.href=u;el.download=name+'-'+lang+'.csv';el.click();URL.revokeObjectURL(u)}
document.addEventListener('click',e=>{let l=e.target.closest('[data-lang]');if(l){lang=l.dataset.lang;localStorage.setItem('cv-lang',lang);translate()}let n=e.target.closest('.nav-item');if(n)show(n.dataset.view);let j=e.target.closest('[data-jump]');if(j)show(j.dataset.jump);let p=e.target.closest('[data-profile]');if(p)profile(p.dataset.profile)});
document.addEventListener('change',e=>{if(e.target.matches('.compare-select'))compareResults();if(e.target.id==='investmentType')simulator();if(e.target.id==='priorityPreset'){w={...PRE[e.target.value]};scores();render()}});document.addEventListener('input',e=>{if(e.target.matches('.weight-input'))setWeight(e.target.dataset.weight,+e.target.value);if(e.target.id==='topN')simulator()});
document.getElementById('metricSelect').onchange=chart;document.getElementById('sortMetric').onchange=e=>{sort=e.target.value;ranking()};document.getElementById('search').oninput=ranking;document.getElementById('exportBtn').onclick=()=>exportRows([...data].sort((a,b)=>b.score-a.score),'cabo-verde-ranking');document.getElementById('exportShortlist').onclick=()=>exportRows([...data].sort((a,b)=>b.score-a.score).slice(0,+document.getElementById('topN').value),'cabo-verde-shortlist');document.getElementById('resetWeights').onclick=()=>{w={...DEF};scores();render()};document.getElementById('menuBtn').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.getElementById('closeProfile').onclick=()=>document.getElementById('profileDialog').close();
fetch('data/municipalities.csv').then(r=>r.text()).then(s=>{data=csv(s);enrich();translate();show(view)}).catch(()=>document.getElementById('main').innerHTML='<p class="empty">Unable to load data.</p>');

function registerWebMCP(){
  const context=document.modelContext;if(!context?.registerTool)return;
  const signal=new AbortController().signal;
  const report=e=>console.warn('WebMCP registration failed',e);
  Promise.resolve(context.registerTool({name:'configure_opportunity_strategy',title:'Configure opportunity strategy',description:'Apply a visible strategy preset and open the decision simulator.',inputSchema:{type:'object',properties:{preset:{type:'string',enum:['balanced','scale','gap','density','impact']},shortlistSize:{type:'integer',minimum:3,maximum:6}},required:['preset'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!PRE[input.preset])throw new Error('Invalid preset');if(input.shortlistSize!==undefined&&(!Number.isInteger(input.shortlistSize)||input.shortlistSize<3||input.shortlistSize>6))throw new Error('Invalid shortlist size');w={...PRE[input.preset]};document.getElementById('priorityPreset').value=input.preset;if(input.shortlistSize)document.getElementById('topN').value=input.shortlistSize;scores();show('simulator');return {preset:input.preset,shortlistSize:+document.getElementById('topN').value,topMunicipality:[...data].sort((a,b)=>b.score-a.score)[0].name}}},{signal})).catch(report);
  Promise.resolve(context.registerTool({name:'read_investment_shortlist',title:'Read investment shortlist',description:'Return the municipality shortlist currently shown by the simulator.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return {weights:{...w},municipalities:[...data].sort((a,b)=>b.score-a.score).slice(0,+document.getElementById('topN').value).map(r=>({municipality:r.name,code:r.Concelho,score:r.score}))}}},{signal})).catch(report);
}
registerWebMCP();
